import {cinemaArtSVG} from './cinema-art.js?v=63.0.0';
export function cinemaAvailability(s,E){const a=E.experienceSpec(s,'cinema');if(a.completed)return {ok:false,reason:'Today’s screening memory is already saved.'};if(s.cash<a.price)return {ok:false,reason:'You need '+E.money(a.price)+' in game money to finish this screening.'};try{E.canAct(s,a.minutes,a.energy,{care:true});return {ok:true,reason:''};}catch(e){return {ok:false,reason:e.message};}}
export function cinemaGuideHTML(s,{E,esc}){const a=E.experienceSpec(s,'cinema'),available=cinemaAvailability(s,E),event=E.calendarToday(s),bonus=event.activity==='cinema'&&!s.eventClaims.includes(s.day),memory=s.activityMemories.find(m=>m.day===s.day&&m.activity==='cinema');return `<div class="modal-body cinema-guide"><span class="eyebrow">DAY ${s.day} · ${esc(E.mallOf(s).name)} · PICTURE HOUSE</span><h3>Today at the picture house.</h3><div class="cinema-programme"><article class="cinema-poster">${cinemaArtSVG(a.film.id)}<small>AN ORIGINAL MALLSIDE ILLUSTRATED SHORT</small><h4>${esc(a.film.title)}</h4><p>Three still scenes · six virtual seats · read at your own pace</p></article><div><h4>A quiet break between shops.</h4><p>${esc(a.film.scenes[0][1])}</p><p>Choose a seat and read all three scenes. You can change seats or close the draft without paying. The ${E.money(a.price)} game charge and ${a.minutes} game minutes apply only when you finish.</p><p>Finishing restores up to ${a.recovery} stamina, adds a journal stamp and 15 XP once per game day across all centers. Ordinary time-related fullness still applies.</p>${bonus?`<p class="hint">${esc(event.name)} also awards ${E.money(event.bonus)} game money and ${event.xp} XP when completed today.</p>`:''}${a.completed?`<p class="hint" role="status">Today’s memory is saved${memory?' · '+esc(memory.title):''}. Return on another game day for the rotating programme.</p>`:!available.ok?`<p class="hint" role="status">${esc(available.reason)}</p>`:''}<p>Original fictional stories and drawings, not real theatre listings or a booking. No movie footage or audio is played.</p></div></div><details class="cinema-poster-archive"><summary>Browse the original poster collection · free</summary><div>${E.CINEMA_SHORTS.map(f=>`<article>${cinemaArtSVG(f.id,1)}<strong>${esc(f.title)}</strong></article>`).join('')}</div><p>The game programme rotates each game day. These posters reserve no seat and change no game money, time or XP.</p></details><button class="button secondary wide" data-action="view" data-id="journal">Requests & weekly calendar</button></div>`;}
export function cinemaGuideFooter(s,{E,esc}){const a=E.experienceSpec(s,'cinema'),v=cinemaAvailability(s,E);return `<div class="cinema-footer"><div><strong>${a.completed?'Watched today ✓':'Choose first, pay at the end'}</strong><small>${E.money(a.price)} game money · ${a.minutes} game min · up to +${a.recovery} stamina</small></div><button class="button orange" data-action="enjoy-activity" data-id="cinema" ${v.ok?'':'disabled'}>${a.completed?'Memory saved':'Choose a seat'}</button></div>`;}
export function cinemaScreeningHTML(s,session,{E,esc}){const a=E.experienceSpec(s,'cinema'),stage=session.stage,c=session.choice,scene=a.film.scenes[Math.max(0,stage-1)];return `<div class="modal-body cinema-screening"><span class="eyebrow">ORIGINAL MALLSIDE ILLUSTRATED SHORT · CLOCK PAUSED</span><h3>${esc(a.film.title)}</h3><ol class="cinema-progress" aria-label="Screening progress">${['Your seat',...a.film.scenes.map(v=>v[0])].map((name,i)=>`<li ${stage===i?'aria-current="step"':''}>${i<stage?'✓ ':''}${esc(name)}</li>`).join('')}</ol>${stage===0?`${cinemaArtSVG(a.film.id)}<fieldset><legend>Choose a virtual seat</legend><div class="cinema-seats">${[1,2,3,4,5,6].map(n=>`<button class="button secondary ${c.seat===n?'selected':''}" data-action="experience-pick" data-id="${n}" aria-pressed="${c.seat===n}"><span aria-hidden="true">▰</span> Seat ${n}</button>`).join('')}</div></fieldset><p class="hint">Seat ${c.seat} selected. Choosing, changing seats and reading are free. The game clock remains paused.</p>`:`${cinemaArtSVG(a.film.id,stage-1)}<section class="cinema-story" role="region" aria-label="Scene ${stage} of 3"><small>SCENE ${stage}/3 · SEAT ${c.seat}</small><h4>${esc(scene[0])}</h4><p>${esc(scene[1])}</p></section><button class="button secondary" data-action="cinema-reseat">Change seat & restart · free</button>`}${session.error?`<p class="experience-error" role="alert">${esc(session.error)}</p>`:''}<p>No charge has been made. Closing cancels this draft. Finish all three scenes to review and pay ${E.money(a.price)} for ${a.minutes} game minutes.</p><button class="button secondary" data-action="cinema-cancel">Cancel & return to the foyer</button></div>`;}
export function cinemaScreeningFooter(s,session,{E,esc}){const a=E.experienceSpec(s,'cinema'),last=session.stage===3;return `<div class="cinema-footer"><div><strong>${last?'Finish the screening':'No charge yet'}</strong><small>${last?E.money(a.price)+' game money · '+a.minutes+' game min · up to +'+a.recovery+' stamina':'Seat '+session.choice.seat+' · '+(session.stage?'scene '+session.stage+'/3':'ready to begin')}</small></div><button class="button orange" data-action="${last?'experience-finish':'cinema-next'}">${last?'Finish & pay '+E.money(a.price):session.stage?'Next scene':'Take this seat'}</button></div>`;}
